'use strict';
let disposeRouteView=null;
function overviewMap(){const selected=id=>state.harvester===id||state.forwarder===id;return `<div class="map-panel"><div class="map-title">Einsatzkarte <span>Echtes Luftbild · fiktive Hiebe</span></div><svg class="map aerial-overview" viewBox="0 0 620 350" role="group" aria-label="Echtes Luftbild mit drei fiktiven Arbeitsgebieten und Nachbargrenze"><image href="${WorksiteRoutes.imageUrl}" width="620" height="350" preserveAspectRatio="none"/><rect width="620" height="350" fill="#00253d" fill-opacity=".15"/>${state.stands.map(site=>{const id=site.id,r=WorksiteRoutes.sites[id],[x,y,k]=r.anchor,h=r.hazard;return `<g transform="translate(${x} ${y}) scale(${k})"><g data-plot="${id}" tabindex="0" role="button" aria-label="${site.name}: beide Maschinen zuweisen"><path class="plot ${selected(id)?'selected':''}" d="${WorksiteRoutes.pathD(r.boundary)} Z"/><path d="${WorksiteRoutes.pathD(r.forwarder)}" fill="none" stroke="#ffdf72" stroke-width=".6" stroke-dasharray="2 1.5"/><path d="${WorksiteRoutes.pathD(r.harvester)}" fill="none" stroke="#52d5ff" stroke-width=".6"/>${WorksiteRoutes.neighbour(id)}<rect x="12" y="48" width="66" height="25" rx="2" fill="#003758" fill-opacity=".9"/><text x="17" y="58" fill="white" font-size="8" font-weight="700">${site.name}${site.closed?' · GESPERRT':''}</text><text x="17" y="67" fill="#d1eaf9" font-size="5.8">${site.species} · Spielbestand</text>${state.harvester===id?'<rect x="25" y="20" width="12" height="12" rx="2" fill="#52d5ff"/><text x="31" y="29" text-anchor="middle" font-size="8" font-weight="700" fill="#003f6b">H</text>':''}${state.forwarder===id?'<rect x="47" y="89" width="12" height="12" rx="2" fill="#ffdf72"/><text x="53" y="98" text-anchor="middle" font-size="8" font-weight="700" fill="#003f6b">F</text>':''}</g><g data-bio="${id}" tabindex="0" role="button" aria-label="${h.label}: Bericht öffnen"><circle cx="${h.x}" cy="${h.z}" r="${h.r}" fill="#ffc37c33" stroke="#ffd369" stroke-width=".6"/><text x="${h.x}" y="${h.z+3}" text-anchor="middle" fill="#ffdf72" font-size="10" font-weight="800" style="paint-order:stroke;stroke:#003858;stroke-width:1">!</text></g></g>`;}).join('')}<g transform="translate(565 23)" fill="white"><text x="0" y="0" font-size="12">N</text><path d="M5 7 V31 M0 14 L5 7 L10 14" fill="none" stroke="white" stroke-width="2"/></g><rect x="16" y="318" width="425" height="22" rx="3" fill="#003758" fill-opacity=".9"/><text x="25" y="333" fill="#e2f3ff" font-size="11">Hieb antippen: beide Maschinen zuweisen</text></svg><div class="map-key"><span>H · Harvester</span><span>F · Forwarder</span><span>! · Schutzbereich</span></div>${WorksiteRoutes.attribution()}<div class="stand-list">${state.stands.map(s=>`<div class="stand"><b>${s.name}${s.closed?' · GESPERRT':''}</b><p>Erkundet: ${s.surveyCoverage} %<br>Auftrag H-${s.id.toUpperCase()}01<br>${s.terrain}<br>${num(s.remaining)} fm stehend</p><span class="stock">${num(s.stock)} fm Waldlager<br>${num(s.roadside)} fm Polter P-${s.id.toUpperCase()}01</span><button class="stand-handover" data-handover="${s.id}">${state.handoverAccepted[s.id]&&state.handoverVersions[s.id]>=(state.round>=3?2:1)?'✓ Übergabe bestätigt':'! Übergabe offen'}</button></div>`).join('')}</div></div>`;}
function openHandover(id=state.harvester){if(!ForestGame.biodiversity[id])throw Error('Unbekannter Arbeitsauftrag.');renderHandover(id);const dialog=document.getElementById('handoverDialog');if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function renderHandover(id){disposeRouteView?.();disposeRouteView=null;const s=state.stands.find(x=>x.id===id),b={...ForestGame.biodiversity[id]},accepted=state.handoverAccepted[id]&&state.handoverVersions[id]>=(state.round>=3?2:1),assignment=[state.harvester===id?'Harvester H-01':null,state.forwarder===id?'Forwarder F-01':null].filter(Boolean).join(' + ')||'Aktuell keine Maschine zugeteilt',felled=s.volume-s.remaining+(s.initialStock||0);if(id==='b'&&s.surveyCoverage===100){b.status='Nacherkundung dokumentiert · Schutzbereich ergänzt';b.instruction='Die ausgelassene Teilfläche wurde geprüft. Neu festgestellten Biotopbereich aussparen und die aktualisierte Markierung beachten.';}const content=document.getElementById('handoverContent');content.innerHTML=`<div class="handover-titlebar"><div><p class="eyebrow">DIGITALER ARBEITSAUFTRAG · DEMOBERICHT</p><h2 id="handoverTitle">Hiebsübergabe · ${s.name}</h2></div><label class="language-picker"><span>Sprache</span><select data-language-select aria-label="Sprache wählen"><option data-no-translate value="de" lang="de">Deutsch</option><option data-no-translate value="en" lang="en">English</option><option data-no-translate value="fr" lang="fr">Français</option></select></label><button class="close-report" id="closeHandover" aria-label="Übergabebericht schließen">✕</button></div><div class="report-tabs" role="group" aria-label="Arbeitsauftrag für Übergabebericht auswählen">${state.stands.map(x=>`<button data-report="${x.id}" class="${x.id===id?'active':''}" aria-pressed="${x.id===id}">${x.name}<small>H-${x.id.toUpperCase()}01 ${state.handoverAccepted[x.id]&&state.handoverVersions[x.id]>=(state.round>=3?2:1)?'· bestätigt':'· offen'}</small></button>`).join('')}</div><div class="report-meta"><div><span>Arbeitsauftrag</span><b>H-${id.toUpperCase()}01 · Version ${state.round>=3?2:1}</b></div><div><span>Übergabe an</span><b>Maschinenteam H-01 / F-01</b></div><div><span>Spielstand</span><b>Schicht ${state.round} von 4</b></div><div><span>Kenntnisnahme</span><b>${accepted?'Bestätigt in Schicht '+state.handoverRound[id]:'Noch offen'}</b></div></div>${WorksiteRoutes.panel(id)}<section class="report-section"><div class="survey-report ${s.surveyCoverage<100?'survey-open':''}"><b>Vorerkundung: ${s.surveyCoverage} % dokumentiert</b><p>${s.surveyCoverage<100?'Die Revierleitung hatte nur begrenzt Zeit. Die nordöstliche Teilfläche wurde nicht begangen. Digitale Kenntnisnahme schließt diese Informationslücke nicht. Vor Einsatz nacherkunden oder Teilfläche aussparen.':'Der bekannte Erkundungsstand ist vollständig dokumentiert. Schutzbereiche bleiben von der Bearbeitung ausgeschlossen.'}</p></div><div class="boundary-report"><b>Flurkarte und Hiebsgrenze</b><p>${id==='a'?'Ostgrenze im Gelände unklar. Orange gestrichelt: fehlerhafte Altskizze. Weiß: geprüfte Auftragsgrenze im Szenario. Die Nachbarfläche gehört nicht zum Auftrag.':'Nur innerhalb der freigegebenen Auftragsgrenze arbeiten.'}</p><p>Planung: ${state.boundary==='digital'?'Geprüfter Hiebsplan als integrierte Kartenebene':state.boundary==='field'?'Papierkarte mit Grenzabgleich vor Ort':'Alte Skizze ohne zusätzliche Prüfung'}. ${state.boundaryChecked[id]?'Grenzabgleich im Spiel dokumentiert.':'Vor Arbeitsbeginn klären.'}</p><small>Die dargestellten Grenzen sind fiktiv. Eine Flurkarte, ein Luftbild oder eine GNSS-Position allein ist keine Hiebsfreigabe.</small></div><h3>01 · Arbeitsumfang und Ausführung</h3><dl class="report-details"><div><dt>Bestand / Baumarten</dt><dd>${s.name} · ${s.species}</dd></div><div><dt>Aktuelles Sortiment</dt><dd>${ForestGame.gradeSpec(state,id)} m Sägeholz · Industrieholz getrennt erfassen (Spielvorgabe)</dd></div><div><dt>Hiebsstatus</dt><dd>${s.closed?'GESPERRT · kein Einsatz möglich':'Planbar außerhalb der Schutzflächen'}</dd></div><div><dt>Einsatzbedingungen</dt><dd>${s.terrain}${state.round===2?' · Niederschlag angekündigt':''}</dd></div><div><dt>Aktuelle Disposition</dt><dd>${assignment}</dd></div><div><dt>Polter und Herkunft</dt><dd>P-${id.toUpperCase()}01 an der Waldstraße · Herkunft H-${id.toUpperCase()}01</dd></div><div><dt>Ausführungshinweis</dt><dd>Nur freigegebene Teilflächen bearbeiten. Markierte Rückegassen und Polterplatz nutzen; Schutzbereiche aussparen.</dd></div><div><dt>Ansprechrolle</dt><dd>Revierleitung · neue Funde vor Ort melden</dd></div></dl></section><section class="report-section"><h3>02 · Mengen und Produktionsfortschritt</h3><div class="report-volumes"><div><strong>${num(s.volume)}</strong><span>fm neu geplant</span></div><div><strong>${num(felled)}</strong><span>fm geerntet</span></div><div><strong>${num(s.stock)}</strong><span>fm Waldlager</span></div><div><strong>${num(s.roadside)}</strong><span>fm noch am Polter</span></div></div><p class="report-note">${num(s.remaining)} fm verbleiben in der geplanten Erntemenge. Geschützte Teilflächen sind nicht zur Bearbeitung freigegeben. Das Anfangs-Waldlager von ${s.initialStock} fm kommt zur neu geplanten Menge hinzu. Bisher ${num(s.delivered||0)} fm an Werk / Industrieabnehmer angeliefert. Die Lkw-Abfuhr folgt nach den vier Ernteschichten.</p></section><section class="report-section"><h3>03 · Biodiversität: Fund im Bestand</h3><article class="bio-finding"><div class="bio-heading"><span class="bio-symbol" aria-hidden="true">!</span><div><b>${b.code} · ${b.title}</b><small>${b.status}</small></div></div><dl class="report-details"><div><dt>Fundort</dt><dd>${b.location} · Marker ${b.code} in der Einsatzkarte</dd></div><div><dt>Maßnahme</dt><dd>${b.instruction}</dd></div><div><dt>Nutzungsbeschränkung</dt><dd><b>${b.restriction}</b></dd></div></dl></article><p class="report-note">Bei neuen Funden im Spiel: Fundbereich aussparen, Hinweis markieren und die Revierleitung informieren. Keine pauschalen Schutzabstände; maßgeblich ist die dokumentierte Markierung.</p></section><section class="report-section report-accept"><h3>04 · Kenntnisnahme durch das Maschinenteam</h3>${accepted?`<div class="accept-confirmed"><b>✓ Kenntnisnahme bestätigt</b><p>Auftrag H-${id.toUpperCase()}01, Version ${state.round>=3?2:1} · Maschinenteam · Schicht ${state.handoverRound[id]}. Die Schutzbereiche bleiben eingeschränkt.</p></div>`:`<p>Bestätige die drei Punkte für die digitale Übergabe. Nicht begangene Teilflächen bleiben weiterhin ungeprüft.</p><label class="report-check"><input type="checkbox" id="checkScope"> Arbeitsauftrag, Hiebsgrenze, Rückegassen und Polterplatz geprüft.</label><label class="report-check"><input type="checkbox" id="checkBio"> Biodiversitätsfund und Schutzmaßnahmen zur Kenntnis genommen.</label><label class="report-check"><input type="checkbox" id="checkRestriction"> Gesperrte und geschützte Bereiche bleiben ausgespart.</label><button class="primary" id="acceptHandover" disabled>Übergabe im Spiel bestätigen</button>`}<p class="report-note">Demofunde und Beispielanweisungen. Die Bestätigung gilt nur für dieses Spiel und ersetzt keine fachliche Freigabe oder reale Hiebsübergabe.</p></section>`;disposeRouteView=RouteFlyover.bind(id);const aerial=document.getElementById('aerialToggle');aerial.onclick=()=>{const layer=content.querySelector('.aerial-layer'),on=aerial.getAttribute('aria-pressed')!=='true';aerial.setAttribute('aria-pressed',String(on));layer.style.display=on?'':'none';aerial.textContent='Luftbild: '+(on?'an':'aus');};document.getElementById('mapZoom').oninput=e=>{content.querySelector('.worksite-map-svg').style.transform='scale('+Number(e.target.value)+')';};document.getElementById('closeHandover').onclick=()=>document.getElementById('handoverDialog').close();content.querySelectorAll('[data-report]').forEach(button=>button.onclick=()=>renderHandover(button.dataset.report));if(!accepted){const checks=['checkScope','checkBio','checkRestriction'],button=document.getElementById('acceptHandover');const ready=()=>checks.every(key=>document.getElementById(key).checked);checks.forEach(key=>document.getElementById(key).onchange=()=>{button.disabled=!ready();});button.onclick=()=>{if(!ready())return;state.handoverAccepted[id]=true;state.handoverRound[id]=state.round;state.handoverVersions[id]=state.round>=3?2:1;render();renderHandover(id);};}}
